div.t-att-style:
'width: 400px; height: 250px;
                                 display: flex; flex-direction: column; justify-content: center;
                                 align-items: center; text-align: center; border: 1px solid #ddd;
                                 border-radius: 10px; box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.1);
                                 background-color:' + (
                record.name.raw_value == 'Design Paper View' and '#e3f2fd' or
                record.name.raw_value == 'Design Paper Create' and '#e8f5e9' or
                record.name.raw_value == 'Question Paper View' and '#fff3e0' or
                '#f9f9f9'
            )
